const { execSync, spawnSync } = require('child_process');
const action = (params.action || 'read').toLowerCase();
const platform = process.platform;
if (action === 'read') {
  if (platform === 'darwin') {
    return { content: execSync('pbpaste', { encoding: 'utf8' }) };
  }
  if (platform === 'win32') {
    const out = execSync('powershell -command Get-Clipboard', { encoding: 'utf8' });
    return { content: out };
  }
  // linux: try xclip then wl-paste
  try { return { content: execSync('xclip -selection clipboard -o', { encoding: 'utf8' }) }; } catch {}
  try { return { content: execSync('wl-paste', { encoding: 'utf8' }) }; } catch {}
  throw new Error('No clipboard reader found (install xclip or wl-clipboard)');
}
if (action === 'write') {
  const text = params.content ?? params.text ?? '';
  if (platform === 'darwin') {
    const r = spawnSync('pbcopy', [], { input: text }); if (r.status !== 0) throw new Error('pbcopy failed'); return { ok: true, bytes: Buffer.byteLength(text) };
  }
  if (platform === 'win32') {
    const r = spawnSync('clip', [], { input: text, shell: false }); if (r.status !== 0) throw new Error('clip failed'); return { ok: true, bytes: Buffer.byteLength(text) };
  }
  // linux
  try { spawnSync('xclip', ['-selection', 'clipboard'], { input: text }); return { ok: true, bytes: Buffer.byteLength(text) }; } catch {}
  try { spawnSync('wl-copy', [], { input: text }); return { ok: true, bytes: Buffer.byteLength(text) }; } catch {}
  throw new Error('No clipboard writer found');
}
throw new Error('Unknown action: ' + action);
